def test_app_routes_coverage():
    with open('web/src/App.jsx') as f:
        content = f.read()
    for path in ['/guide', '/terms', '/privacy', '/pricing']:
        assert f"'{path}':" in content, f'Missing path mapping for {path} in App.jsx'
    for view in ['pricing:', 'study:']:
        assert view in content or f"pricing: [" in content, f'Missing legacy view alias for {view}'

def test_legal_entity_defined():
    for path in ['web/src/components/TermsOfServiceView.jsx', 'web/src/components/PrivacyPolicyView.jsx']:
        with open(path) as f:
            assert 'Helpotron Autonomous Systems LLC' in f.read(), f'Entity missing in {path}'
